package kz.structure.reminder;
import android.app.*;import android.os.*;import android.content.*;import android.provider.Settings;import android.net.Uri;import android.graphics.Color;import android.widget.*;import java.util.*;import java.text.*;
public class MainActivity extends Activity {
 LinearLayout layout; EditText partner,guests; Calendar date=Calendar.getInstance(); TextView time;
 TextView label(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(Color.WHITE);t.setPadding(8,12,8,12);layout.addView(t);return t;}
 void base(){ScrollView scroll=new ScrollView(this);layout=new LinearLayout(this);layout.setOrientation(1);layout.setPadding(24,48,24,32);layout.setBackgroundColor(0xff101820);scroll.addView(layout);setContentView(scroll);}
 void button(String s,Runnable r){Button b=new Button(this);b.setText(s);layout.addView(b);b.setOnClickListener(v->r.run());}
 EditText field(String hint){EditText e=new EditText(this);e.setHint(hint);layout.addView(e);return e;}
 String fmt(long t,String f){return new SimpleDateFormat(f,new Locale("ru","RU")).format(new Date(t));}
 public void onCreate(Bundle b){super.onCreate(b);if(getIntent().hasExtra("stage"))showAlarm(getIntent());else home();}
 protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);if(i.hasExtra("stage"))showAlarm(i);else home();}
 void home(){if(Build.VERSION.SDK_INT>=27){setShowWhenLocked(false);setTurnScreenOn(false);}getWindow().clearFlags(android.view.WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);base();label("СОЗДАНИЕ СТРУКТУРЫ",22);label("Напоминания о встречах",28);partner=field("Имя партнёра");guests=field("Гости (по одному на строку)");date=Calendar.getInstance();date.add(Calendar.HOUR,7);time=label(fmt(date.getTimeInMillis(),"dd.MM.yyyy HH:mm"),30);button("Выбрать дату и время",()->new DatePickerDialog(this,(v,y,m,d)->{date.set(y,m,d);new TimePickerDialog(this,(w,h,min)->{date.set(Calendar.HOUR_OF_DAY,h);date.set(Calendar.MINUTE,min);date.set(Calendar.SECOND,0);time.setText(fmt(date.getTimeInMillis(),"dd.MM.yyyy HH:mm"));},date.get(Calendar.HOUR_OF_DAY),date.get(Calendar.MINUTE),true).show();},date.get(Calendar.YEAR),date.get(Calendar.MONTH),date.get(Calendar.DAY_OF_MONTH)).show());button("Разрешения будильника",()->{if(Build.VERSION.SDK_INT>=31&&!getSystemService(AlarmManager.class).canScheduleExactAlarms())startActivity(new Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:"+getPackageName())));else if(Build.VERSION.SDK_INT>=34&&!getSystemService(NotificationManager.class).canUseFullScreenIntent())startActivity(new Intent(Settings.ACTION_MANAGE_APP_USE_FULL_SCREEN_INTENT,Uri.parse("package:"+getPackageName())));else Toast.makeText(this,"Разрешения будильника предоставлены",0).show();});button("Сохранить встречу",()->schedule());button("Предпросмотр наставника",()->showAlarm(data(2,date.getTimeInMillis(),900).putExtra("mentor",true)));button("Предпросмотр запроса подтверждения",()->showAlarm(data(2,date.getTimeInMillis(),901).putExtra("mentor",true).putExtra("approval",true)));button("Тест: два коротких через 10 секунд",()->test(6));button("Тест: три коротких через 10 секунд",()->test(2));if(Build.VERSION.SDK_INT>=33)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},1);}
 Intent data(int stage,long meeting,int id){return new Intent(this,AlarmReceiver.class).putExtra("stage",stage).putExtra("meeting",meeting).putExtra("partner",partner.getText().toString()).putExtra("guests",guests.getText().toString()).putExtra("id",id);}
 boolean set(Intent i,long when){AlarmManager a=getSystemService(AlarmManager.class);if(Build.VERSION.SDK_INT>=31&&!a.canScheduleExactAlarms()){Toast.makeText(this,"Разрешите точные будильники",1).show();return false;}PendingIntent p=PendingIntent.getBroadcast(this,i.getIntExtra("id",0),i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);PendingIntent show=PendingIntent.getActivity(this,i.getIntExtra("id",0),new Intent(this,MainActivity.class).putExtras(i),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);a.setAlarmClock(new AlarmManager.AlarmClockInfo(when,show),p);return true;}
 void test(int stage){set(data(stage,System.currentTimeMillis()+10000+stage*3600000L,stage),System.currentTimeMillis()+10000);}
 void schedule(){long m=date.getTimeInMillis();int count=0;for(int s:new int[]{6,2}){long t=m-s*3600000L;if(t>System.currentTimeMillis()&&set(data(s,m,(int)(m/60000)*10+s),t))count++;}Toast.makeText(this,"Запланировано сигналов: "+count,1).show();}

 String shortName(String name){if(name==null)return "";String[] a=name.trim().split("\\s+");return a.length>=2?a[1]+" "+a[0].substring(0,1)+".":name;}
 void action(String s,int color,Runnable run){Button b=new Button(this);b.setAllCaps(false);b.setText(s);b.setTextSize(18);b.setTextColor(Color.WHITE);android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable();bg.setColor(color);bg.setCornerRadius(18);b.setBackground(bg);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,8,0,8);layout.addView(b,lp);b.setOnClickListener(v->run.run());}
 void centered(String s,int size,int color){TextView t=label(s,size);t.setGravity(17);t.setTypeface(null,1);t.setTextColor(color);}
 void dismissAlarm(Intent i){getSystemService(NotificationManager.class).cancel(i.getIntExtra("id",0));finish();}
 void comment(Intent i){EditText e=new EditText(this);e.setHint("Причина / комментарий");new AlertDialog.Builder(this).setTitle("Закрыть с комментарием").setView(e).setNegativeButton("Отмена",null).setPositiveButton("Сохранить локально",(d,w)->{if(e.getText().toString().trim().isEmpty()){Toast.makeText(this,"Укажите причину",0).show();return;}getPreferences(0).edit().putString("comment_"+i.getIntExtra("id",0),e.getText().toString()).apply();dismissAlarm(i);}).show();}
 void showAlarm(Intent i){if(Build.VERSION.SDK_INT>=27){setShowWhenLocked(true);setTurnScreenOn(true);}else getWindow().addFlags(0x80000|0x200000);getWindow().addFlags(android.view.WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);base();boolean mentor=i.getBooleanExtra("mentor",false),approval=i.getBooleanExtra("approval",false);layout.setBackgroundColor(mentor?0xff281b10:0xff081b30);int gold=mentor?0xffffd58a:0xffb8ddff;long m=i.getLongExtra("meeting",0);String names=shortName(i.getStringExtra("partner"))+" — "+i.getStringExtra("guests");if(approval){centered("Встреча состоялась! Прошу подтверждение?",22,gold);}else{if(!mentor)centered("МОЁ НАПОМИНАНИЕ",22,gold);centered(fmt(m,"HH:mm"),79,Color.WHITE);centered(fmt(m,"d MMMM · EEEE"),27,Color.WHITE);}centered("ОРР  |  "+names,25,gold);if(approval)centered(fmt(m,"d MMMM · EEEE · HH:mm"),22,Color.WHITE);if(mentor){if(approval){action("Подтверждаю",0xff168b40,()->Toast.makeText(this,"Предпросмотр: база не подключена",1).show());action("Отклонить",0xff40444a,()->comment(i));}else{action("Напомнить в WhatsApp",0xff168b40,()->Toast.makeText(this,"Номер партнёра ещё не подключён",1).show());action("Связаться с партнёром",0xff40444a,()->Toast.makeText(this,"Номер партнёра ещё не подключён",1).show());action("Открыть его план",0xff40444a,()->Toast.makeText(this,"Ссылка на план ещё не подключена",1).show());}}else{action("Подтвердить встречу",0xff168b40,()->dismissAlarm(i));action("Отложить на 10 минут",0xff245a92,()->{Intent n=new Intent(this,AlarmReceiver.class).putExtras(i);if(set(n,System.currentTimeMillis()+600000))dismissAlarm(i);});action("Закрыть с комментарием",0xff40444a,()->comment(i));}}
}
